// Step 1: Format Interpretation Bundle Parameters
const input = $input.first().json;

const userId = input.user_id;
const ingestionId = input.ingestion_id;
const sourceTextId = input.source_text_id;
const interpretation = input.interpretation || input;
const rawOutput = input.raw_output || JSON.stringify(interpretation);
const provider = input.provider || 'openai';
const model = input.model || 'gpt-5.6-luna';

return [{
  json: {
    ...input,
    user_id: userId,
    ingestion_id: ingestionId,
    source_text_id: sourceTextId,
    interpretation: interpretation,
    raw_output: rawOutput,
    provider: provider,
    model: model
  }
}];

const req = $('Prepare Interpretation Bundle').first().json;
const resRaw = $input.first().json.res;
const res = typeof resRaw === 'string' ? JSON.parse(resRaw) : resRaw;

return [{
  json: {
    ok: true,
    status: 'completed',
    correlation_id: req.correlation_id,
    data: {
      ...res,
      applied_at: new Date().toISOString()
    }
  }
}];
